result:=result||jsonb_build_object('keep:artecna_contabilita.attribuzioni_clienti',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t."id") ORDER BY jsonb_build_object('id',t."id")::text),'[]') FROM artecna_contabilita.attribuzioni_clienti t WHERE t.cantiere_id=cid));

result:=result||jsonb_build_object('keep:public.agenda_attivita',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t."id") ORDER BY jsonb_build_object('id',t."id")::text),'[]') FROM public.agenda_attivita t WHERE t.collegamento->>'tipo'='cantiere' AND t.collegamento->>'id'=cid::text));
result:=result||jsonb_build_object('keep:artecna_contabilita.archivio_quote',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t."id") ORDER BY jsonb_build_object('id',t."id")::text),'[]') FROM artecna_contabilita.archivio_quote t WHERE t.fattura_riga_id IN(SELECT e.fattura_riga_id FROM public.economia_righe e JOIN public.economia_raccolte r ON r.id=e.raccolta_id WHERE r.cantiere_id=cid UNION SELECT m.fattura_riga_id FROM public.materiali_cantiere m WHERE m.cantiere_id=cid UNION SELECT f.id FROM public.fatture_fornitori_righe f WHERE f.cantiere_id=cid)));
result:=result||jsonb_build_object('keep:artecna_contabilita.archivio_attribuzioni',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t."id") ORDER BY jsonb_build_object('id',t."id")::text),'[]') FROM artecna_contabilita.archivio_attribuzioni t WHERE t.fattura_id IN(SELECT id FROM public.fatture_emesse WHERE cantiere_id=cid UNION SELECT fattura_id FROM artecna_contabilita.attribuzioni_clienti WHERE cantiere_id=cid)));
witness_ids:=ARRAY(SELECT DISTINCT x FROM(SELECT unnest(runtime_ids) x UNION ALL SELECT CASE WHEN r.value->>'id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN (r.value->>'id')::uuid END FROM jsonb_each(result) e CROSS JOIN LATERAL jsonb_array_elements(e.value) r WHERE e.key NOT LIKE 'keep:%') known WHERE x IS NOT NULL ORDER BY x);
result:=result||jsonb_build_object('keep:artecna_guardie.fatture_classificazione_richieste',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',t."user_id",'richiesta_id',t."richiesta_id") ORDER BY jsonb_build_object('user_id',t."user_id",'richiesta_id',t."richiesta_id")::text),'[]') FROM artecna_guardie.fatture_classificazione_richieste t WHERE EXISTS(SELECT 1 FROM artecna_distruzione.runtime_ownership_edges e WHERE e.user_id=t.user_id AND e.richiesta_id=t.richiesta_id AND e.referenced_uuid=ANY(witness_ids))));
result:=result||jsonb_build_object('keep:runtime:ids',to_jsonb(runtime_ids),'keep:runtime:witness_ids',to_jsonb(witness_ids));RETURN artecna_distruzione.hard_delete_shared_scope(cid,result); END $function$
;
CREATE FUNCTION artecna_distruzione.hard_delete_legal_witnesses(targets jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT jsonb_build_object('transition:quote',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(j::text),'' ORDER BY md5(j::text)),''))) FROM (SELECT jsonb_build_object('tipo','economia','fattura_riga_id',t.fattura_riga_id,'quantita',t.quantita,'netto',t.quantita*t.prezzo_unitario,'costo',t.quantita*t.prezzo_unitario,'descrizione',artecna_distruzione.sanifica_archivio(to_jsonb(t.descrizione),ARRAY(SELECT jsonb_array_elements_text(targets->'keep:runtime:ids'))::uuid[])#>>'{}') j FROM jsonb_to_recordset(coalesce(targets->'public.economia_righe','[]')) AS k("id" uuid) JOIN public.economia_righe t ON t."id"=k."id" WHERE t.fattura_riga_id IS NOT NULL
UNION ALL SELECT jsonb_build_object('tipo','materiale','fattura_riga_id',t.fattura_riga_id,'quantita',t.quantita,'netto',t.quantita*t.prezzo_unitario,'costo',t.totale,'descrizione',artecna_distruzione.sanifica_archivio(to_jsonb(t.descrizione),ARRAY(SELECT jsonb_array_elements_text(targets->'keep:runtime:ids'))::uuid[])#>>'{}') j FROM jsonb_to_recordset(coalesce(targets->'public.materiali_cantiere','[]')) AS k("id" uuid) JOIN public.materiali_cantiere t ON t."id"=k."id" WHERE t.fattura_riga_id IS NOT NULL
UNION ALL SELECT jsonb_build_object('tipo',t.tipo,'fattura_riga_id',t.fattura_riga_id,'quantita',t.quantita,'netto',t.netto,'costo',t.costo,'descrizione',t.descrizione) j FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'public.fatture_fornitori_righe','[]')||coalesce(targets->'keep:public.fatture_fornitori_righe','[]')||coalesce(targets->'keep:shared:public.fatture_fornitori_righe','[]')) AS k("id" uuid)) k JOIN artecna_contabilita.archivio_quote t ON t.fattura_riga_id=k.id) rows),'transition:attribuzioni',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(j::text),'' ORDER BY md5(j::text)),''))) FROM (SELECT jsonb_build_object('fattura_id',t.fattura_id,'cliente',artecna_distruzione.sanifica_archivio(to_jsonb(t.cliente_confermato),ARRAY(SELECT jsonb_array_elements_text(targets->'keep:runtime:ids'))::uuid[])#>>'{}','importo',t.importo,'verificato',t.verificato,'creato_at',t.creato_at,'scollegato',t.scollegato_at IS NOT NULL) j FROM jsonb_to_recordset(coalesce(targets->'keep:artecna_contabilita.attribuzioni_clienti','[]')) AS k("id" uuid) JOIN artecna_contabilita.attribuzioni_clienti t ON t."id"=k."id"
UNION ALL SELECT jsonb_build_object('fattura_id',t.fattura_id,'cliente',t.cliente,'importo',t.importo,'verificato',t.verificato,'creato_at',t.creato_at,'scollegato',t.scollegato) j FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'public.fatture_emesse','[]')||coalesce(targets->'keep:public.fatture_emesse','[]')||coalesce(targets->'keep:shared:public.fatture_emesse','[]')) AS k("id" uuid)) k JOIN artecna_contabilita.archivio_attribuzioni t ON t.fattura_id=k.id) rows)) $$;
REVOKE ALL ON FUNCTION artecna_distruzione.hard_delete_legal_witnesses(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION artecna_distruzione.hard_delete_preserved(cid uuid,targets jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ DECLARE result jsonb:='{}';runtime_ids uuid[]:=ARRAY(SELECT jsonb_array_elements_text(targets->'keep:runtime:ids'))::uuid[]; BEGIN IF NOT(targets ? 'keep:runtime:ids') THEN RAISE EXCEPTION 'Witness identities missing' USING ERRCODE='P2113';END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_contabilita.archivio_attribuzioni','[]')||coalesce(targets->'keep:artecna_contabilita.archivio_attribuzioni','[]'))>0 THEN result:=result||jsonb_build_object('artecna_contabilita.archivio_attribuzioni',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_contabilita.archivio_attribuzioni','[]')||coalesce(targets->'keep:artecna_contabilita.archivio_attribuzioni','[]')) AS k("id" uuid)) k JOIN artecna_contabilita.archivio_attribuzioni t ON t."id"=k."id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_contabilita.archivio_quote','[]')||coalesce(targets->'keep:artecna_contabilita.archivio_quote','[]'))>0 THEN result:=result||jsonb_build_object('artecna_contabilita.archivio_quote',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_contabilita.archivio_quote','[]')||coalesce(targets->'keep:artecna_contabilita.archivio_quote','[]')) AS k("id" uuid)) k JOIN artecna_contabilita.archivio_quote t ON t."id"=k."id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_contabilita.attribuzioni_clienti','[]')||coalesce(targets->'keep:artecna_contabilita.attribuzioni_clienti','[]'))>0 THEN result:=result||jsonb_build_object('artecna_contabilita.attribuzioni_clienti',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_contabilita.attribuzioni_clienti','[]')||coalesce(targets->'keep:artecna_contabilita.attribuzioni_clienti','[]')) AS k("id" uuid)) k JOIN artecna_contabilita.attribuzioni_clienti t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'keep:artecna_contabilita.attribuzioni_clienti','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_guardie.fatture_classificazione_richieste','[]')||coalesce(targets->'keep:artecna_guardie.fatture_classificazione_richieste','[]'))>0 THEN result:=result||jsonb_build_object('artecna_guardie.fatture_classificazione_richieste',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((CASE WHEN EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'keep:artecna_guardie.fatture_classificazione_richieste','[]')) AS x("user_id" uuid,"richiesta_id" uuid) WHERE t."user_id"=x."user_id" AND t."richiesta_id"=x."richiesta_id") THEN to_jsonb(t)-ARRAY['payload','risultato']||jsonb_build_object('payload',artecna_distruzione.sanifica_archivio(t.payload,runtime_ids),'risultato',artecna_distruzione.sanifica_archivio(t.risultato,runtime_ids)) ELSE to_jsonb(t) END)::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_guardie.fatture_classificazione_richieste','[]')||coalesce(targets->'keep:artecna_guardie.fatture_classificazione_richieste','[]')) AS k("user_id" uuid,"richiesta_id" uuid)) k JOIN artecna_guardie.fatture_classificazione_richieste t ON t."user_id"=k."user_id" AND t."richiesta_id"=k."richiesta_id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_rapportini.allegati','[]'))>0 THEN result:=result||jsonb_build_object('artecna_rapportini.allegati',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_rapportini.allegati','[]')) AS k("id" uuid)) k JOIN artecna_rapportini.allegati t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'artecna_rapportini.allegati','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_rapportini.f3c3_capability','[]'))>0 THEN result:=result||jsonb_build_object('artecna_rapportini.f3c3_capability',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_rapportini.f3c3_capability','[]')) AS k("foto_id" uuid)) k JOIN artecna_rapportini.f3c3_capability t ON t."foto_id"=k."foto_id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'artecna_rapportini.f3c3_capability','[]')) AS x("foto_id" uuid) WHERE t."foto_id"=x."foto_id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_rapportini.richieste','[]'))>0 THEN result:=result||jsonb_build_object('artecna_rapportini.richieste',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_rapportini.richieste','[]')) AS k("canale" text,"utente_id" uuid,"richiesta_id" uuid)) k JOIN artecna_rapportini.richieste t ON t."canale"=k."canale" AND t."utente_id"=k."utente_id" AND t."richiesta_id"=k."richiesta_id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'artecna_rapportini.richieste','[]')) AS x("canale" text,"utente_id" uuid,"richiesta_id" uuid) WHERE t."canale"=x."canale" AND t."utente_id"=x."utente_id" AND t."richiesta_id"=x."richiesta_id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:artecna_rapportini.sessioni_portale','[]'))>0 THEN result:=result||jsonb_build_object('artecna_rapportini.sessioni_portale',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:artecna_rapportini.sessioni_portale','[]')) AS k("token_sha256" bytea)) k JOIN artecna_rapportini.sessioni_portale t ON t."token_sha256"=k."token_sha256"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.acconti_cantiere','[]'))>0 THEN result:=result||jsonb_build_object('public.acconti_cantiere',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.acconti_cantiere','[]')) AS k("id" uuid)) k JOIN public.acconti_cantiere t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.acconti_cantiere','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.agenda_attivita','[]')||coalesce(targets->'keep:public.agenda_attivita','[]'))>0 THEN result:=result||jsonb_build_object('public.agenda_attivita',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((CASE WHEN EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'keep:public.agenda_attivita','[]')) AS x("id" uuid) WHERE t."id"=x."id") THEN to_jsonb(t)-ARRAY['collegamento'] ELSE to_jsonb(t) END)::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.agenda_attivita','[]')||coalesce(targets->'keep:public.agenda_attivita','[]')) AS k("id" uuid)) k JOIN public.agenda_attivita t ON t."id"=k."id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.attrezzi_cantiere','[]'))>0 THEN result:=result||jsonb_build_object('public.attrezzi_cantiere',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.attrezzi_cantiere','[]')) AS k("id" uuid)) k JOIN public.attrezzi_cantiere t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.attrezzi_cantiere','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
