IF jsonb_array_length(coalesce(targets->'keep:shared:public.utenti_cantiere','[]'))>0 THEN result:=result||jsonb_build_object('public.utenti_cantiere',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.utenti_cantiere','[]')) AS k("cantiere_id" uuid,"user_id" uuid)) k JOIN public.utenti_cantiere t ON t."cantiere_id"=k."cantiere_id" AND t."user_id"=k."user_id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.utenti_cantiere','[]')) AS x("cantiere_id" uuid,"user_id" uuid) WHERE t."cantiere_id"=x."cantiere_id" AND t."user_id"=x."user_id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.utenti_impresa','[]'))>0 THEN result:=result||jsonb_build_object('public.utenti_impresa',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.utenti_impresa','[]')) AS k("user_id" uuid)) k JOIN public.utenti_impresa t ON t."user_id"=k."user_id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.utilizzo_ai','[]'))>0 THEN result:=result||jsonb_build_object('public.utilizzo_ai',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.utilizzo_ai','[]')) AS k("id" uuid)) k JOIN public.utilizzo_ai t ON t."id"=k."id"  OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_documenti','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_documenti',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_documenti','[]')) AS k("id" uuid)) k JOIN public.variante_documenti t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_documenti','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_fonti_memory','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_fonti_memory',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_fonti_memory','[]')) AS k("variante_id" uuid,"source_type" text,"source_id" uuid)) k JOIN public.variante_fonti_memory t ON t."variante_id"=k."variante_id" AND t."source_type"=k."source_type" AND t."source_id"=k."source_id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_fonti_memory','[]')) AS x("variante_id" uuid,"source_type" text,"source_id" uuid) WHERE t."variante_id"=x."variante_id" AND t."source_type"=x."source_type" AND t."source_id"=x."source_id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_fonti_visive','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_fonti_visive',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_fonti_visive','[]')) AS k("variante_id" uuid,"source_type" text,"source_id" uuid)) k JOIN public.variante_fonti_visive t ON t."variante_id"=k."variante_id" AND t."source_type"=k."source_type" AND t."source_id"=k."source_id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_fonti_visive','[]')) AS x("variante_id" uuid,"source_type" text,"source_id" uuid) WHERE t."variante_id"=x."variante_id" AND t."source_type"=x."source_type" AND t."source_id"=x."source_id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_lavorazioni','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_lavorazioni',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_lavorazioni','[]')) AS k("id" bigint)) k JOIN public.variante_lavorazioni t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_lavorazioni','[]')) AS x("id" bigint) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_osservatore_analisi','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_osservatore_analisi',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_osservatore_analisi','[]')) AS k("id" uuid)) k JOIN public.variante_osservatore_analisi t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_osservatore_analisi','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.variante_sorgenti','[]'))>0 THEN result:=result||jsonb_build_object('public.variante_sorgenti',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.variante_sorgenti','[]')) AS k("id" uuid)) k JOIN public.variante_sorgenti t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.variante_sorgenti','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
IF jsonb_array_length(coalesce(targets->'keep:shared:public.varianti_cantiere','[]'))>0 THEN result:=result||jsonb_build_object('public.varianti_cantiere',(SELECT jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(h,'' ORDER BY h),''))) FROM (SELECT md5((to_jsonb(t))::text) h FROM (SELECT DISTINCT * FROM jsonb_to_recordset(coalesce(targets->'keep:shared:public.varianti_cantiere','[]')) AS k("id" uuid)) k JOIN public.varianti_cantiere t ON t."id"=k."id" WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(coalesce(targets->'public.varianti_cantiere','[]')) AS x("id" uuid) WHERE t."id"=x."id") OFFSET 0) frozen));END IF;
RETURN result||artecna_distruzione.hard_delete_legal_witnesses(targets);END $$;
CREATE OR REPLACE FUNCTION artecna_distruzione.hard_delete_blockers(cid uuid, targets jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE blockers text[]:='{}';legacy_source record;legacy_row record;ids uuid[];target_name text;fk record;joins text;bad boolean;parent_key text;child_key text;candidate_filter text;legacy_projection text; BEGIN
 IF artecna_distruzione.hard_delete_catalog() IS DISTINCT FROM (SELECT signature FROM artecna_distruzione.hard_delete_catalog_expected) THEN RETURN ARRAY['catalogo']; END IF;
 SELECT nome INTO target_name FROM public.cantieri WHERE id=cid;
 FOR legacy_source IN SELECT * FROM artecna_distruzione.legacy_sorgenti ORDER BY tabella LOOP
  CASE legacy_source.tabella WHEN 'public.acconti_cantiere' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.attrezzi_cantiere' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.fatture_emesse' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.fatture_fornitori_righe' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.foto_cantiere' THEN candidate_filter:='t.cantiere=$2 OR t.allegato_v1_id IN(SELECT id FROM artecna_rapportini.allegati WHERE cantiere_id=$1)';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere",''allegato_v1_id'',t."allegato_v1_id")';
WHEN 'public.incassi_non_fatturati' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.materiali_cantiere' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.memoria_prezzi' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.pagamenti_fornitori' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.preventivi_cantiere' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.preventivo_lavorazioni' THEN candidate_filter:='t.cantiere=$2 OR t.preventivo_id IN(SELECT id FROM public.preventivi_cantiere WHERE cantiere_id=$1)';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere",''preventivo_id'',t."preventivo_id")';
WHEN 'public.rapportini' THEN candidate_filter:='t.cantiere=$2';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere")';
WHEN 'public.sal_lavorazioni' THEN candidate_filter:='t.cantiere=$2 OR t.source_lavorazione_id IN(SELECT id FROM public.preventivo_lavorazioni WHERE cantiere_id=$1) OR t.source_variante_lavorazione_id IN(SELECT l.id FROM public.variante_lavorazioni l JOIN public.varianti_cantiere v ON v.id=l.variante_id WHERE v.cantiere_id=$1)';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere",''source_lavorazione_id'',t."source_lavorazione_id",''source_variante_lavorazione_id'',t."source_variante_lavorazione_id")';
WHEN 'public.timbrature' THEN candidate_filter:='t.cantiere=$2 OR t.prestazione_rapportino_id IN(SELECT p.id FROM public.rapportino_prestazioni p JOIN public.rapportini r ON r.id=p.rapportino_id WHERE r.cantiere_id=$1)';legacy_projection:='jsonb_build_object(''cantiere'',t."cantiere",''prestazione_rapportino_id'',t."prestazione_rapportino_id")'; ELSE RETURN ARRAY['legacy_source_non_classificata'];END CASE;
  FOR legacy_row IN EXECUTE format('SELECT %s j FROM %s t WHERE cantiere_id IS NULL AND (%s)',legacy_projection,legacy_source.relation,candidate_filter) USING cid,target_name LOOP
   ids:=artecna_distruzione.legacy_derivazione(legacy_source.tabella,legacy_row.j);
   IF cid=ANY(ids) OR (cardinality(ids)=0 AND legacy_row.j->>'cantiere'=target_name) THEN blockers:=array_append(blockers,'legacy_ambiguo');EXIT; END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM artecna_distruzione.legacy_da_risolvere WHERE approved_cantiere=cid) THEN blockers:=array_append(blockers,'legacy_ambiguo'); END IF;
 IF EXISTS(SELECT 1 FROM artecna_rapportini.allegati WHERE cantiere_id=cid AND lease_until>clock_timestamp()) THEN blockers:=array_append(blockers,'upload_in_corso'); END IF;
 -- Concordance of every populated ownership path, including logical non-FK edges.
 IF EXISTS(SELECT 1 FROM artecna_rapportini.allegati a JOIN public.rapportini r ON r.id=a.rapportino_id WHERE (a.cantiere_id=cid OR r.cantiere_id=cid) AND a.cantiere_id IS DISTINCT FROM r.cantiere_id)
 OR EXISTS(SELECT 1 FROM public.foto_cantiere f JOIN public.rapportini r ON r.id::text=f.rapportino_id WHERE (f.cantiere_id=cid OR r.cantiere_id=cid) AND f.cantiere_id IS DISTINCT FROM r.cantiere_id)
 OR EXISTS(SELECT 1 FROM public.timbrature t JOIN public.rapportini r ON r.id=t.rapportino_id WHERE (t.cantiere_id=cid OR r.cantiere_id=cid) AND t.cantiere_id IS DISTINCT FROM r.cantiere_id)
 OR EXISTS(SELECT 1 FROM public.rapportino_prestazioni p JOIN public.rapportini r ON r.id=p.rapportino_id JOIN public.varianti_cantiere v ON v.id=p.variante_id WHERE (r.cantiere_id=cid OR v.cantiere_id=cid) AND r.cantiere_id IS DISTINCT FROM v.cantiere_id)
 OR EXISTS(SELECT 1 FROM public.variante_sorgenti s JOIN public.varianti_cantiere v ON v.id=s.variante_id JOIN public.economia_raccolte e ON e.id=s.economia_raccolta_id WHERE (v.cantiere_id=cid OR e.cantiere_id=cid) AND v.cantiere_id IS DISTINCT FROM e.cantiere_id)
 THEN blockers:=array_append(blockers,'ownership_discordante'); END IF;

 FOR fk IN SELECT k.*,k.conrelid::regclass::text child,k.confrelid::regclass::text parent FROM pg_constraint k WHERE k.contype='f' AND targets ? k.confrelid::regclass::text LOOP
  SELECT string_agg(format('f.%I=p.%I',a.attname,b.attname),' AND ' ORDER BY u.o) INTO joins FROM unnest(fk.conkey,fk.confkey) WITH ORDINALITY u(a,b,o) JOIN pg_attribute a ON a.attrelid=fk.conrelid AND a.attnum=u.a JOIN pg_attribute b ON b.attrelid=fk.confrelid AND b.attnum=u.b;
  parent_key:=(SELECT 'jsonb_build_object('||string_agg(quote_literal(a.attname)||',p.'||quote_ident(a.attname),',' ORDER BY u.o)||')' FROM pg_constraint k CROSS JOIN LATERAL unnest(k.conkey) WITH ORDINALITY u(n,o) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=u.n WHERE k.contype='p' AND k.conrelid=fk.confrelid);child_key:=(SELECT 'jsonb_build_object('||string_agg(quote_literal(a.attname)||',f.'||quote_ident(a.attname),',' ORDER BY u.o)||')' FROM pg_constraint k CROSS JOIN LATERAL unnest(k.conkey) WITH ORDINALITY u(n,o) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=u.n WHERE k.contype='p' AND k.conrelid=fk.conrelid);
  IF parent_key IS NULL OR (targets ? fk.child AND child_key IS NULL) THEN RETURN ARRAY['fk_non_classificata'];END IF;
  IF targets ? fk.child THEN
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s f JOIN %s p ON %s WHERE EXISTS(SELECT 1 FROM jsonb_array_elements($1->$2) k WHERE %s @> k.value) IS DISTINCT FROM EXISTS(SELECT 1 FROM jsonb_array_elements($1->$3) k WHERE %s @> k.value))',fk.conrelid::regclass,fk.confrelid::regclass,joins,parent_key,child_key) INTO bad USING targets,fk.parent,fk.child;
  ELSIF fk.child IN ('public.fornitori_rettifiche','public.fatture_emesse','public.fatture_fornitori_righe','artecna_contabilita.attribuzioni_clienti','artecna_distruzione.contesto','artecna_distruzione.contesto_prerequisiti','artecna_distruzione.quote_da_eliminare') THEN CONTINUE;
  ELSE
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s f JOIN %s p ON %s WHERE EXISTS(SELECT 1 FROM jsonb_array_elements($1->$2) k WHERE %s @> k.value))',fk.conrelid::regclass,fk.confrelid::regclass,joins,parent_key,child_key) INTO bad USING targets,fk.parent;
  END IF;
  IF bad THEN blockers:=array_append(blockers,'relazione_esterna');EXIT;END IF;
 END LOOP;
 RETURN blockers; END $function$
;
CREATE OR REPLACE FUNCTION artecna_distruzione.hard_delete_blockers(cid uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT artecna_distruzione.hard_delete_blockers(cid,artecna_distruzione.hard_delete_targets(cid)) $$;
REVOKE ALL ON FUNCTION artecna_distruzione.hard_delete_blockers(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION artecna_distruzione.hard_delete_blockers(uuid,jsonb) TO artecna_cantieri_delete_rpc;

GRANT artecna_cantieri_delete_rpc TO postgres WITH ADMIN FALSE, INHERIT FALSE, SET TRUE GRANTED BY postgres;
DO $$ BEGIN IF(SELECT needs_create FROM pg_temp.artecna_009_state) THEN GRANT CREATE ON SCHEMA public TO artecna_cantieri_delete_rpc;END IF;END $$;
SET ROLE artecna_cantieri_delete_rpc;
CREATE OR REPLACE FUNCTION public.elimina_cantiere_definitivamente(p_cantiere_id uuid, p_conferma text)
 RETURNS TABLE(cantiere_id uuid, eliminato boolean, storage_nuovi bigint, conteggi jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE cid uuid:=p_cantiere_id;targets jsonb;preserved jsonb;after_keep jsonb;blockers text[];tab text;n bigint;expected bigint;total bigint;oldmax bigint;objects jsonb;shared bigint;legal_count bigint;legacy_count bigint;
BEGIN
 IF current_user<>'artecna_cantieri_delete_rpc' OR cid IS NULL OR p_conferma IS DISTINCT FROM 'ELIMINA' THEN RAISE EXCEPTION 'UUID e conferma esatta ELIMINA obbligatori' USING ERRCODE='P2111'; END IF;
 PERFORM artecna_distruzione.apri_contesto_prerequisiti(cid,p_conferma);
 -- Coarse, deterministic locks protect logical links without FK as well as FK
 -- links. Do not replace with root locks alone. No network I/O under these locks.
 PERFORM artecna_distruzione.hard_delete_lock(cid);
 targets:=artecna_distruzione.hard_delete_targets(cid);
 blockers:=artecna_distruzione.hard_delete_blockers(cid,targets);
 IF cardinality(blockers)>0 THEN RAISE EXCEPTION 'Hard delete bloccato: %',array_to_string(blockers,', ') USING ERRCODE='P2113'; END IF;
 PERFORM artecna_distruzione.inizia_contesto(cid);

 INSERT INTO artecna_distruzione.hard_delete_plan VALUES(pg_current_xact_id(),pg_backend_pid(),cid,targets::text);
 preserved:=artecna_distruzione.hard_delete_preserved(cid,targets);
 SELECT coalesce(max(id),0) INTO oldmax FROM artecna_distruzione.cleanup_storage;
 SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('bucket',r.bucket,'path',r.path)),'[]') INTO objects FROM artecna_distruzione.storage_riferimenti r
 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(targets->r.source_table,'[]')) k WHERE r.source_id=k.value);
 -- Prepare exclusive keys BEFORE source DELETE. A live reference outside the
 -- frozen target set preserves the object. Existing jobs are never overwritten.
 INSERT INTO artecna_distruzione.cleanup_storage(cantiere_id,bucket,path)
 SELECT cid,o->>'bucket',o->>'path' FROM jsonb_array_elements(objects) o WHERE NOT EXISTS(
 SELECT 1 FROM artecna_distruzione.storage_riferimenti r WHERE r.bucket=o->>'bucket' AND r.path=o->>'path'
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(targets->r.source_table,'[]')) k WHERE r.source_id=k.value)) ON CONFLICT DO NOTHING;
 SELECT coalesce(sum(jsonb_array_length(value)),0) INTO legal_count FROM jsonb_each(targets) WHERE key IN ('keep:public.fornitori_rettifiche','keep:public.fatture_emesse','keep:public.fatture_fornitori_righe','keep:artecna_contabilita.attribuzioni_clienti');
 SELECT coalesce(sum(jsonb_array_length(targets->tabella)),0) INTO legacy_count FROM artecna_distruzione.legacy_sorgenti;
 PERFORM artecna_distruzione.detach_contabile_cantiere();
 UPDATE public.agenda_attivita SET collegamento=NULL WHERE collegamento->>'tipo'='cantiere' AND collegamento->>'id'=cid::text;
 UPDATE public.cantieri SET preventivo_contrattuale_id=NULL WHERE id=cid AND preventivo_contrattuale_id IS NOT NULL;
 UPDATE public.foto_cantiere f SET allegato_v1_id=NULL WHERE f.cantiere_id=cid AND f.allegato_v1_id IS NOT NULL;
 conteggi:='{}';
total:=0; LOOP
 DELETE FROM artecna_rapportini.richieste t WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(targets->'artecna_rapportini.richieste') k WHERE jsonb_build_object('canale',t."canale",'utente_id',t."utente_id",'richiesta_id',t."richiesta_id")=k.value)  ;
 GET DIAGNOSTICS n=ROW_COUNT;total:=total+n;EXIT WHEN n=0;END LOOP;
 expected:=jsonb_array_length(targets->'artecna_rapportini.richieste');IF total<>expected THEN RAISE EXCEPTION 'Delete/manifest divergente: artecna_rapportini.richieste' USING ERRCODE='P2114'; END IF;
 conteggi:=conteggi||jsonb_build_object('artecna_rapportini.richieste',total);
total:=0; LOOP
 DELETE FROM public.sal_lavorazioni t WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(targets->'public.sal_lavorazioni') k WHERE jsonb_build_object('id',t."id")=k.value)  ;
 GET DIAGNOSTICS n=ROW_COUNT;total:=total+n;EXIT WHEN n=0;END LOOP;
 expected:=jsonb_array_length(targets->'public.sal_lavorazioni');IF total<>expected THEN RAISE EXCEPTION 'Delete/manifest divergente: public.sal_lavorazioni' USING ERRCODE='P2114'; END IF;
 conteggi:=conteggi||jsonb_build_object('public.sal_lavorazioni',total);
total:=0; LOOP
 DELETE FROM public.variante_fonti_memory t WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(targets->'public.variante_fonti_memory') k WHERE jsonb_build_object('variante_id',t."variante_id",'source_type',t."source_type",'source_id',t."source_id")=k.value)  ;
 GET DIAGNOSTICS n=ROW_COUNT;total:=total+n;EXIT WHEN n=0;END LOOP;
 expected:=jsonb_array_length(targets->'public.variante_fonti_memory');IF total<>expected THEN RAISE EXCEPTION 'Delete/manifest divergente: public.variante_fonti_memory' USING ERRCODE='P2114'; END IF;
